try (java.io.InputStream is = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(grid_png))) {
    net.coobird.thumbnailator.ThumbnailParameter param = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder()
            .size(50, 50)
            .build();

    net.coobird.thumbnailator.tasks.io.InputStreamImageSource source = new net.coobird.thumbnailator.tasks.io.InputStreamImageSource(is);
    net.coobird.thumbnailator.tasks.io.BufferedImageSink destination = new net.coobird.thumbnailator.tasks.io.BufferedImageSink();

    net.coobird.thumbnailator.Thumbnailator.createThumbnail(
        new net.coobird.thumbnailator.tasks.SourceSinkThumbnailTask<>(param, source, destination)
    );

    java.awt.image.BufferedImage thumbnail = destination.getSink();

    assert thumbnail != null : "Thumbnail should not be null";
    assert thumbnail.getWidth() <= 50 && thumbnail.getHeight() <= 50 : "Thumbnail dimensions should be bounded by 50x50";

    System.out.println("__CHECK__ InputStreamImageSource " + thumbnail.getWidth() + "x" + thumbnail.getHeight());
}

